import json, sys

def flatten_content(content):
    out = []
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        for blk in content:
            if isinstance(blk, dict):
                t = blk.get('type')
                if t == 'text':
                    out.append(blk.get('text',''))
                elif t == 'thinking':
                    out.append('[THINKING] ' + blk.get('thinking',''))
                elif t == 'tool_use':
                    name = blk.get('name','')
                    inp = blk.get('input',{})
                    out.append(f'[TOOL_USE {name}] ' + json.dumps(inp)[:8000])
                elif t == 'tool_result':
                    c = blk.get('content','')
                    out.append('[TOOL_RESULT] ' + (flatten_content(c) if not isinstance(c,str) else c))
                else:
                    out.append(json.dumps(blk)[:2000])
            else:
                out.append(str(blk))
    elif isinstance(content, dict):
        return flatten_content([content])
    return '\n'.join(out)

def main(path):
    recnum=0
    for line in open(path, errors='replace'):
        line=line.strip()
        if not line: continue
        try:
            o=json.loads(line)
        except Exception:
            continue
        recnum+=1
        typ=o.get('type','')
        role=''
        text=''
        m=o.get('message')
        if isinstance(m,dict):
            role=m.get('role','')
            text=flatten_content(m.get('content',''))
        elif o.get('attachment'):
            text='[ATTACHMENT] '+json.dumps(o.get('attachment'))[:4000]
        else:
            text=json.dumps(o)[:1000]
        ts=o.get('timestamp','')
        # Emit as REC marker lines so grep -n context maps to records
        for ln in text.split('\n'):
            print(f'@@REC{recnum}|{typ}|{role}|{ts}@@ {ln}')

if __name__=='__main__':
    main(sys.argv[1])
